-- Designing a URL Shortener
insert into public.articles (owner_id, slug, title) values ('00000000-0000-4000-a000-000000000002', 'url-shortener', 'Designing a URL Shortener');
-- (separate statements: the draft row is created by the on_article_created trigger)
update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"url-shortener-s-2","frameId":"url-shortener-frame-1"},"content":[{"type":"text","text":"Requirements"}]},{"type":"paragraph","content":[{"type":"text","text":"Users submit a long URL and get a short alias; visiting the alias redirects to the original."}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"100M new URLs a month"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reads outnumber writes 100 : 1"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Redirect under 50 ms"}]}]}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"Non-goals for v1: custom domains, analytics dashboards and editing a link after it is created."}]},{"type":"heading","attrs":{"level":2,"sectionId":"url-shortener-s-9","frameId":"url-shortener-frame-8"},"content":[{"type":"text","text":"High-level design"}]},{"type":"paragraph","content":[{"type":"text","text":"Clients call a stateless API service behind a load balancer. Short codes map to long URLs in a key-value store."}]},{"type":"callout","attrs":{"tone":"mint"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Key idea: generate IDs from a counter and encode them in base62 — 7 characters give 3.5 trillion codes."}]}]},{"type":"details","attrs":{"tone":"sky"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Why not hash the long URL?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Hashes collide and need a retry loop; a counter never collides and keeps codes short."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"url-shortener-s-j","frameId":"url-shortener-frame-i"},"content":[{"type":"text","text":"Scaling reads"}]},{"type":"paragraph","content":[{"type":"text","text":"Most traffic is redirects, so cache hot codes at the edge and in Redis; misses go to read replicas."}]},{"type":"callout","attrs":{"tone":"red"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Watch out: cache 301 redirects carefully — browsers keep them forever."}]}]}]}'::jsonb, canvas = '{"layout":"50-50","files":{},"elements":[{"id":"url-shortener-frame-1","type":"frame","x":0,"y":0,"width":1400,"height":1400,"name":"Requirements","seed":1,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"url-shortener-el-3","frameId":"url-shortener-frame-1","seed":1536533497,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":120,"y":220,"width":320,"height":130,"strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-4","frameId":"url-shortener-frame-1","seed":1553311116,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":191.76,"y":267.5,"width":176.48000000000002,"height":35,"text":"Shorten URL","originalText":"Shorten URL","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-5","frameId":"url-shortener-frame-1","seed":1570088735,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":540,"y":220,"width":320,"height":130,"strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-6","frameId":"url-shortener-frame-1","seed":1586866354,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":596.0799999999999,"y":267.5,"width":207.84000000000003,"height":35,"text":"Redirect fast","originalText":"Redirect fast","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-7","frameId":"url-shortener-frame-1","seed":1603643973,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"arrow","x":440,"y":285,"width":96,"height":0,"points":[[0,0],[96,0]],"strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roundness":null,"lastCommittedPoint":null,"startArrowhead":null,"endArrowhead":"arrow","elbowed":false},{"id":"url-shortener-frame-8","type":"frame","x":7400,"y":0,"width":1400,"height":1400,"name":"High-level design","seed":2,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"url-shortener-el-a","frameId":"url-shortener-frame-8","seed":697652547,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":7520,"y":220,"width":320,"height":130,"strokeColor":"#0369a1","backgroundColor":"#e0f2fe","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-b","frameId":"url-shortener-frame-8","seed":714430166,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":7630.96,"y":267.5,"width":98.08000000000001,"height":35,"text":"Client","originalText":"Client","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-c","frameId":"url-shortener-frame-8","seed":731207785,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":7940,"y":220,"width":320,"height":130,"strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-d","frameId":"url-shortener-frame-8","seed":747985404,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":8011.76,"y":267.5,"width":176.48000000000002,"height":35,"text":"API service","originalText":"API service","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-e","frameId":"url-shortener-frame-8","seed":764763023,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"arrow","x":7840,"y":285,"width":96,"height":0,"points":[[0,0],[96,0]],"strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roundness":null,"lastCommittedPoint":null,"startArrowhead":null,"endArrowhead":"arrow","elbowed":false},{"id":"url-shortener-el-f","frameId":"url-shortener-frame-8","seed":781540642,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":8360,"y":220,"width":320,"height":130,"strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-g","frameId":"url-shortener-frame-8","seed":798318261,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":8400.4,"y":267.5,"width":239.20000000000002,"height":35,"text":"Key-value store","originalText":"Key-value store","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-h","frameId":"url-shortener-frame-8","seed":815095880,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"arrow","x":8260,"y":285,"width":96,"height":0,"points":[[0,0],[96,0]],"strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roundness":null,"lastCommittedPoint":null,"startArrowhead":null,"endArrowhead":"arrow","elbowed":false},{"id":"url-shortener-frame-i","type":"frame","x":14800,"y":0,"width":1400,"height":1400,"name":"Scaling reads","seed":3,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"url-shortener-el-k","frameId":"url-shortener-frame-i","seed":865428737,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":14920,"y":220,"width":320,"height":130,"strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-l","frameId":"url-shortener-frame-i","seed":882206356,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":14991.76,"y":267.5,"width":176.48000000000002,"height":35,"text":"CDN / cache","originalText":"CDN / cache","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-m","frameId":"url-shortener-frame-i","seed":898983975,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":15340,"y":220,"width":320,"height":130,"strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-n","frameId":"url-shortener-frame-i","seed":915761594,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":15396.08,"y":267.5,"width":207.84000000000003,"height":35,"text":"Read replicas","originalText":"Read replicas","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-o","frameId":"url-shortener-frame-i","seed":932539213,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"arrow","x":15240,"y":285,"width":96,"height":0,"points":[[0,0],[96,0]],"strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roundness":null,"lastCommittedPoint":null,"startArrowhead":null,"endArrowhead":"arrow","elbowed":false}]}'::jsonb, version = version + 1, updated_at = now()
