-- Consistent Hashing
insert into public.articles (owner_id, slug, title) values ('00000000-0000-4000-a000-000000000002', 'consistent-hashing', 'Consistent Hashing');
-- (separate statements: the draft row is created by the on_article_created trigger)
update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-2","frameId":"consistent-hashing-frame-1"},"content":[{"type":"text","text":"Why naive hashing breaks"}]},{"type":"paragraph","content":[{"type":"text","text":"You run "},{"type":"text","text":"N cache servers","marks":[{"type":"bold"}]},{"type":"text","text":" in front of a database and need to decide which server stores each key. The obvious rule is "},{"type":"text","text":"server = hash(key) % N","marks":[{"type":"code"}]},{"type":"text","text":": fast, stateless, and every client computes the same answer."}]},{"type":"paragraph","content":[{"type":"text","text":"It works until "},{"type":"text","text":"N changes","marks":[{"type":"bold"}]},{"type":"text","text":". Add one server (more traffic) or lose one (a crash), and almost every key suddenly maps to a different server. The caches are effectively empty, every request falls through to the database at once, and the database can fall over. This is a "},{"type":"text","text":"cache stampede","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"callout","attrs":{"tone":"red"},"content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"% N","marks":[{"type":"code"}]},{"type":"text","text":", going from N to N+1 servers moves about "},{"type":"text","text":"N/(N+1)","marks":[{"type":"bold"}]},{"type":"text","text":" of all keys: 75% when growing from 3 to 4 servers, 99% when growing from 100 to 101."}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Servers (before → after)"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys moved with "},{"type":"text","text":"% N","marks":[{"type":"code"}]}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys moved with consistent hashing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"3 → 4"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"75%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"25%"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"10 → 11"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"91%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"9%"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"100 → 101"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"99%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1%"}]}]}]}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Why does modulo move N/(N+1) of the keys?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"A key stays on the same server only if "},{"type":"text","text":"h % N == h % (N+1)","marks":[{"type":"code"}]},{"type":"text","text":". For uniformly random "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" that happens for N out of every N·(N+1) values, i.e. with probability "},{"type":"text","text":"1/(N+1)","marks":[{"type":"bold"}]},{"type":"text","text":". So the fraction that moves is "},{"type":"text","text":"1 − 1/(N+1) = N/(N+1)","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"The drawing shows it with 8 keys whose hashes are 10…17: five of the eight change server when we go from 3 to 4 servers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"What we want instead: when a server joins or leaves, "},{"type":"text","text":"only the keys that must move","marks":[{"type":"bold"}]},{"type":"text","text":" should move. That is about "},{"type":"text","text":"K/N","marks":[{"type":"bold"}]},{"type":"text","text":" keys (K keys, N servers), the new server''s fair share. This is exactly what "},{"type":"text","text":"consistent hashing","marks":[{"type":"bold"}]},{"type":"text","text":" guarantees. It was introduced by Karger et al. at MIT in 1997 for web caching and became the basis of Akamai''s CDN."}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"hash(key) % N","marks":[{"type":"code"}]},{"type":"text","text":" remaps ~N/(N+1) of keys whenever N changes → cold caches, database stampede"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Goal: move only ~K/N keys on any membership change"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-2s","frameId":"consistent-hashing-frame-2r"},"content":[{"type":"text","text":"The hash ring"}]},{"type":"paragraph","content":[{"type":"text","text":"Take the output range of a hash function, for example "},{"type":"text","text":"0 to 2³²−1","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"bend it into a circle","marks":[{"type":"bold"}]},{"type":"text","text":": after the largest value comes 0 again. This circle is the "},{"type":"text","text":"hash ring","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Now hash "},{"type":"text","text":"servers and keys with the same function","marks":[{"type":"bold"}]},{"type":"text","text":", so both land somewhere on the ring. A server''s position is usually "},{"type":"text","text":"hash(server id or IP)","marks":[{"type":"code"}]},{"type":"text","text":"; a key''s position is "},{"type":"text","text":"hash(key)","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"callout","attrs":{"tone":"mint"},"content":[{"type":"paragraph","content":[{"type":"text","text":"The ring is only a picture. In code it is a "},{"type":"text","text":"sorted list of numbers","marks":[{"type":"bold"}]},{"type":"text","text":" that wraps around at the end."}]}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Which hash function?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"It must spread values "},{"type":"text","text":"uniformly","marks":[{"type":"bold"}]},{"type":"text","text":" and give the "},{"type":"text","text":"same result on every machine and in every language","marks":[{"type":"bold"}]},{"type":"text","text":", because clients and servers must agree."}]},{"type":"paragraph","content":[{"type":"text","text":"Common choices: "},{"type":"text","text":"MurmurHash3","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"xxHash","marks":[{"type":"bold"}]},{"type":"text","text":" (fast, not cryptographic), or the first bytes of "},{"type":"text","text":"MD5","marks":[{"type":"bold"}]},{"type":"text","text":" (used by the classic memcached "},{"type":"text","text":"ketama","marks":[{"type":"italic"}]},{"type":"text","text":" library). Never use a language''s built-in "},{"type":"text","text":"hashCode()","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"hash()","marks":[{"type":"code"}]},{"type":"text","text":": it can differ between processes, versions or platforms."}]}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash space 0…2³²−1 wraps around into a ring"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Servers and keys are hashed with the same, stable function"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-3f","frameId":"consistent-hashing-frame-3e"},"content":[{"type":"text","text":"Finding a key''s server"}]},{"type":"paragraph","content":[{"type":"text","text":"To find a key''s server, start at the key''s position and "},{"type":"text","text":"walk clockwise","marks":[{"type":"bold"}]},{"type":"text","text":" until you reach a server. That server owns the key."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash the key → position "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the first server whose position is "},{"type":"text","text":"≥ p","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"None? "},{"type":"text","text":"Wrap around","marks":[{"type":"bold"}]},{"type":"text","text":" to the first server on the ring."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"So every server owns the "},{"type":"text","text":"arc between the previous server and itself","marks":[{"type":"bold"}]},{"type":"text","text":". In the drawing, A owns (C, A], B owns (A, B] and C owns (B, C]. Key k3 sits between B and C, so it belongs to C."}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"Every client that knows the same server list computes the same answer "},{"type":"text","text":"without asking anyone","marks":[{"type":"bold"}]},{"type":"text","text":". That is why memcached client libraries could shard data on their own, with no central router."}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Owner = first server clockwise from the key (wrap around at the end)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each server owns the arc (previous server, itself]"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-4b","frameId":"consistent-hashing-frame-4a"},"content":[{"type":"text","text":"Adding and removing servers"}]},{"type":"paragraph","content":[{"type":"text","text":"Adding a server D","marks":[{"type":"bold"}]},{"type":"text","text":" between A and B: D takes over only the keys between A and D, which used to belong to B. Every other key stays exactly where it was."}]},{"type":"paragraph","content":[{"type":"text","text":"Removing a server","marks":[{"type":"bold"}]},{"type":"text","text":" (or a crash): its keys move to the "},{"type":"text","text":"next server clockwise","marks":[{"type":"bold"}]},{"type":"text","text":". Again, no other key moves."}]},{"type":"callout","attrs":{"tone":"mint"},"content":[{"type":"paragraph","content":[{"type":"text","text":"On average only "},{"type":"text","text":"K/N keys move","marks":[{"type":"bold"}]},{"type":"text","text":" (K keys, N servers). That is the minimum possible: the new server has to get its fair share from somewhere."}]}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"The catch: a new server relieves only "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" neighbour, and a removed server dumps its whole load on "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" neighbour. With few servers that is very uneven. Virtual nodes, in the next section, fix it."}]},{"type":"details","attrs":{"tone":"sky"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Worked example: 4 servers, 1 million keys, add a 5th"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Modulo:","marks":[{"type":"bold"}]},{"type":"text","text":" about 800,000 keys move (4/5 of them). The cache hit rate collapses."}]},{"type":"paragraph","content":[{"type":"text","text":"Ring:","marks":[{"type":"bold"}]},{"type":"text","text":" about 200,000 keys move (1/5), all taken from one neighbour."}]},{"type":"paragraph","content":[{"type":"text","text":"Ring with virtual nodes:","marks":[{"type":"bold"}]},{"type":"text","text":" still about 200,000 keys, but ~50,000 come from each of the four old servers, so the load stays even."}]}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add: the new server takes keys only from its clockwise neighbour"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Remove: its keys go to the next server clockwise"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only ~K/N keys move"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-5l","frameId":"consistent-hashing-frame-5k"},"content":[{"type":"text","text":"Virtual nodes"}]},{"type":"paragraph","content":[{"type":"text","text":"With only a few random positions, the arcs have very different lengths, so one server can own half the ring. "},{"type":"text","text":"Virtual nodes","marks":[{"type":"bold"}]},{"type":"text","text":" (vnodes) fix this: each physical server is placed at "},{"type":"text","text":"many","marks":[{"type":"bold"}]},{"type":"text","text":" positions, for example "},{"type":"text","text":"hash(\"A#1\")","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"hash(\"A#2\")","marks":[{"type":"code"}]},{"type":"text","text":" … "},{"type":"text","text":"hash(\"A#200\")","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Many small arcs average out, so each server ends up with close to its fair share of keys."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Even load:","marks":[{"type":"bold"}]},{"type":"text","text":" the spread between servers shrinks roughly like 1/√V (V = vnodes per server)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Smooth scaling:","marks":[{"type":"bold"}]},{"type":"text","text":" a new server takes a small slice from "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" other server, not just one neighbour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Graceful failure:","marks":[{"type":"bold"}]},{"type":"text","text":" a failed server''s load spreads over all survivors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Different machine sizes:","marks":[{"type":"bold"}]},{"type":"text","text":" give a bigger machine more vnodes (weighting)."}]}]}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"How uneven is it without virtual nodes?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"With one random position per server, the largest arc is about "},{"type":"text","text":"(ln N)/N","marks":[{"type":"bold"}]},{"type":"text","text":" of the ring, i.e. about ln N times the fair share. With 10 servers the busiest server typically gets more than twice the average load."}]},{"type":"paragraph","content":[{"type":"text","text":"With 100–200 vnodes per server the busiest server is usually within about 10% of the average."}]}]}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"Costs: the lookup table grows to N × V entries (still small: 100 servers × 200 vnodes = 20,000 numbers), and rebalancing moves many small ranges instead of one big one. Cassandra used 256 vnodes per node for years, then lowered the default to 16 together with a smarter token-allocation algorithm."}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each server gets many positions: A#1, A#2, … (typically 100–256)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evens out load, spreads joins/failures over all servers, enables weights"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-7e","frameId":"consistent-hashing-frame-7d"},"content":[{"type":"text","text":"Implementation"}]},{"type":"paragraph","content":[{"type":"text","text":"In code, the ring is just a "},{"type":"text","text":"sorted array of (position, server)","marks":[{"type":"bold"}]},{"type":"text","text":" pairs. A lookup is a "},{"type":"text","text":"binary search","marks":[{"type":"bold"}]},{"type":"text","text":" for the first position ≥ hash(key), wrapping to index 0 at the end."}]},{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"import bisect\nimport hashlib\n\n\ndef h(s: str) -> int:\n    \"\"\"Stable 64-bit hash: same result on every machine and in every process.\"\"\"\n    return int.from_bytes(hashlib.md5(s.encode()).digest()[:8], \"big\")\n\n\nclass HashRing:\n    def __init__(self, vnodes: int = 100):\n        self.vnodes = vnodes\n        self.tokens: list[int] = []        # sorted ring positions\n        self.owner: dict[int, str] = {}    # position -> server\n\n    def add(self, server: str) -> None:\n        for i in range(self.vnodes):\n            t = h(f\"{server}#{i}\")\n            bisect.insort(self.tokens, t)\n            self.owner[t] = server\n\n    def remove(self, server: str) -> None:\n        for i in range(self.vnodes):\n            t = h(f\"{server}#{i}\")\n            self.tokens.remove(t)\n            del self.owner[t]\n\n    def get(self, key: str) -> str:\n        if not self.tokens:\n            raise LookupError(\"no servers\")\n        i = bisect.bisect_left(self.tokens, h(key))\n        return self.owner[self.tokens[i % len(self.tokens)]]   # wrap around\n\n\nring = HashRing()\nfor s in (\"cache-a\", \"cache-b\", \"cache-c\"):\n    ring.add(s)\nprint(ring.get(\"user:42\"))"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Operation"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Notes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log(N·V))","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary search over N servers × V vnodes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Add / remove a server"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(V · log(N·V))","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Plus moving ~K/N keys of data"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N·V)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"100 servers × 200 vnodes = 20,000 entries"}]}]}]}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Production notes"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Rebuild, don''t mutate:","marks":[{"type":"bold"}]},{"type":"text","text":" build a new sorted array on each membership change and swap it in atomically, so lookups never take a lock."}]},{"type":"paragraph","content":[{"type":"text","text":"Membership","marks":[{"type":"bold"}]},{"type":"text","text":" comes from a coordination service (ZooKeeper, etcd, Consul) or a gossip protocol (Cassandra, Dynamo). All clients must converge on the same server list, or they will disagree about owners."}]},{"type":"paragraph","content":[{"type":"text","text":"Token collisions","marks":[{"type":"bold"}]},{"type":"text","text":" between two servers are astronomically rare with 64-bit hashes; break ties by server id if you want to be strict."}]}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorted array of (token, server) + binary search"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup O(log(N·V)); wrap to index 0 past the end"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-84","frameId":"consistent-hashing-frame-83"},"content":[{"type":"text","text":"Replication"}]},{"type":"paragraph","content":[{"type":"text","text":"Servers fail, so important data is stored on "},{"type":"text","text":"several servers","marks":[{"type":"bold"}]},{"type":"text","text":". With a replication factor of 3, a key lives on its owner plus the "},{"type":"text","text":"next 2 distinct physical servers","marks":[{"type":"bold"}]},{"type":"text","text":" clockwise. Amazon''s Dynamo calls this list the key''s "},{"type":"text","text":"preference list","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"With virtual nodes you must "},{"type":"text","text":"skip positions belonging to a server that is already in the list","marks":[{"type":"bold"}]},{"type":"text","text":". Otherwise two \"replicas\" could be the same machine, and one crash would lose both."}]},{"type":"callout","attrs":{"tone":"red"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Replication factor 3 survives losing any 2 of the 3 servers, but only if they are really different machines, ideally in different racks or availability zones."}]}]},{"type":"heading","attrs":{"level":3,"visibility":"detail"},"content":[{"type":"text","text":"Quorums"}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"With N replicas, a write waits for "},{"type":"text","text":"W","marks":[{"type":"bold"}]},{"type":"text","text":" acknowledgements and a read asks "},{"type":"text","text":"R","marks":[{"type":"bold"}]},{"type":"text","text":" replicas. If "},{"type":"text","text":"R + W > N","marks":[{"type":"bold"}]},{"type":"text","text":", every read set overlaps the latest write set, so reads see the newest value (for example N = 3, W = 2, R = 2). Lower W or R trades consistency for latency and availability."}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Sloppy quorum and hinted handoff"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"If a replica is down, Dynamo-style systems write to the "},{"type":"text","text":"next healthy server","marks":[{"type":"bold"}]},{"type":"text","text":" on the ring instead, with a "},{"type":"text","text":"hint","marks":[{"type":"italic"}]},{"type":"text","text":" saying who the data really belongs to. When the original server comes back, the data is handed back to it. Writes keep succeeding during short outages."}]},{"type":"paragraph","content":[{"type":"text","text":"Rack/zone awareness (e.g. Cassandra''s NetworkTopologyStrategy) keeps walking the ring until replicas are in different racks or zones."}]}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replicas = owner + next R−1 distinct physical servers clockwise"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Skip vnodes of servers already chosen; spread over racks/zones"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"R + W > N → reads see the latest write"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-90","frameId":"consistent-hashing-frame-8z"},"content":[{"type":"text","text":"Hot keys and uneven load"}]},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing balances "},{"type":"text","text":"keys","marks":[{"type":"bold"}]},{"type":"text","text":", not "},{"type":"text","text":"traffic","marks":[{"type":"bold"}]},{"type":"text","text":". One very popular key (a celebrity''s profile, a viral post) still lives on one server and can overload it. The usual fixes:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Technique"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"How it works"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Trade-off"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Weights","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"More vnodes for bigger machines, so they own more of the ring"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Static: doesn''t react to traffic"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Bounded loads","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Cap every server at (1+ε) × the average load; if the owner is full, keep walking clockwise"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"A few keys move as load shifts"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Hot-key splitting","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Store the hot key as "},{"type":"text","text":"key#1 … key#k","marks":[{"type":"code"}]},{"type":"text","text":" on several servers; read a random copy"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Writes must update every copy"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Local / near cache","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the hottest keys in the client or proxy memory for a few seconds"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Slightly stale reads"}]}]}]}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Consistent hashing with bounded loads"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Proposed by Mirrokni, Thorup and Zadimoghaddam (Google, 2017). Each server accepts at most ⌈(1+ε) · average⌉ requests or connections. A key whose owner is full goes to the next server clockwise that has room."}]},{"type":"paragraph","content":[{"type":"text","text":"It keeps most of consistent hashing''s stability while guaranteeing that no server is overloaded. Vimeo used it for video caching, and HAProxy supports it ("},{"type":"text","text":"hash-balance-factor","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Balances keys, not traffic: hot keys still overload one server"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fixes: weights, bounded loads (1+ε), hot-key splitting, local caches"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-9v","frameId":"consistent-hashing-frame-9u"},"content":[{"type":"text","text":"Alternatives"}]},{"type":"paragraph","content":[{"type":"text","text":"The ring with virtual nodes is not the only way to get \"minimal movement\". Know the alternatives and when each one wins:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Approach"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Balance"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Membership changes"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Best for"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Ring + vnodes","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log(N·V))","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N·V)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Good (more vnodes = better)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any server, any time"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Caches and storage clusters that grow and fail"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Rendezvous (HRW)","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Excellent"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any server, any time"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Small server sets (up to ~100), simple code"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Jump consistent hash","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log N)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Perfect"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Only add/remove the "},{"type":"text","text":"last","marks":[{"type":"bold"}]},{"type":"text","text":" bucket"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Numbered shards of a storage system"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Maglev","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fixed table (e.g. 65,537)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Near perfect"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any; a few % of keys move"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Packet / connection load balancers"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Range sharding","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log S)","marks":[{"type":"code"}]},{"type":"text","text":" (metadata)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Range table"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Managed by splits"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Move ranges explicitly"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Ordered keys and range scans (Bigtable, CockroachDB)"}]}]}]}]},{"type":"details","attrs":{"tone":"sky"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Rendezvous hashing in one paragraph"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"For a key, compute "},{"type":"text","text":"score = hash(key, server)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" server and pick the highest. When a server leaves, only its keys move (each to its second-best server). When one joins, it wins only the keys where it now scores highest. No ring and no vnodes, but O(N) per lookup."}]}]}]},{"type":"details","attrs":{"tone":"sky","visibility":"detail"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Jump consistent hash in one paragraph"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Lamping and Veach (Google, 2014): a ~5-line function "},{"type":"text","text":"jump(key, num_buckets)","marks":[{"type":"code"}]},{"type":"text","text":" that maps a 64-bit key to bucket 0…n−1 with perfect balance and no memory. Growing from n to n+1 buckets moves exactly 1/(n+1) of keys. Limitation: buckets are numbered, so you can only add or remove at the end, which makes it a poor fit for random server failures."}]}]}]},{"type":"callout","attrs":{"tone":"mint"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rule of thumb: "},{"type":"text","text":"ring + vnodes","marks":[{"type":"bold"}]},{"type":"text","text":" for dynamic clusters, "},{"type":"text","text":"rendezvous","marks":[{"type":"bold"}]},{"type":"text","text":" for small server sets, "},{"type":"text","text":"jump hash","marks":[{"type":"bold"}]},{"type":"text","text":" for fixed numbered shards, "},{"type":"text","text":"Maglev","marks":[{"type":"bold"}]},{"type":"text","text":" for packet-level load balancing, "},{"type":"text","text":"ranges","marks":[{"type":"bold"}]},{"type":"text","text":" when you need ordered scans."}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rendezvous: highest hash(key, server) wins, O(N), no ring"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jump hash: O(1) memory, perfect balance, only add/remove at the end"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maglev: O(1) lookup table for load balancers"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-aa","frameId":"consistent-hashing-frame-a9"},"content":[{"type":"text","text":"Where it''s used"}]},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing shows up wherever many machines share data or traffic and machines come and go:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"System"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"How it uses consistent hashing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Amazon Dynamo / DynamoDB","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Partitions items over storage nodes on a ring; preference lists for replication"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Apache Cassandra / ScyllaDB","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Token ring with vnodes; replicas are the next nodes on the ring (rack/DC aware)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Memcached clients (ketama)","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"The client library picks the cache server; no central router"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Nginx, Envoy, HAProxy","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"hash … consistent","marks":[{"type":"code"}]},{"type":"text","text":" / ring-hash / Maglev load balancing keeps a user on the same backend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Akamai and other CDNs","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Decide which edge server caches which URL"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Discord, chat and gaming backends","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Route all events for one channel/room/user to the same process"}]}]}]}]},{"type":"callout","attrs":{"tone":"red"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Interview trap: "},{"type":"text","text":"Redis Cluster does not use a hash ring.","marks":[{"type":"bold"}]},{"type":"text","text":" It uses "},{"type":"text","text":"16,384 fixed hash slots","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"CRC16(key) mod 16384","marks":[{"type":"code"}]},{"type":"text","text":") assigned to nodes, and moves whole slots when the cluster changes. Same goal, different mechanism."}]}]},{"type":"paragraph","attrs":{"visibility":"detail"},"content":[{"type":"text","text":"Where the ring lives: "},{"type":"text","text":"in the client library","marks":[{"type":"bold"}]},{"type":"text","text":" (ketama, Cassandra drivers that are token-aware), "},{"type":"text","text":"in a proxy","marks":[{"type":"bold"}]},{"type":"text","text":" in front of the caches (twemproxy, mcrouter, Envoy), or "},{"type":"text","text":"inside the database","marks":[{"type":"bold"}]},{"type":"text","text":" itself (Cassandra, Dynamo)."}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dynamo/DynamoDB, Cassandra, memcached clients, Nginx/Envoy/HAProxy, CDNs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Redis Cluster uses 16,384 hash slots instead (common trap)"}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-ba","frameId":"consistent-hashing-frame-b9"},"content":[{"type":"text","text":"Interview cheat sheet"}]},{"type":"paragraph","content":[{"type":"text","text":"Explain it in this order and you cover what interviewers look for:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Problem:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"hash % N","marks":[{"type":"code"}]},{"type":"text","text":" remaps ~N/(N+1) of keys when N changes → cache stampede."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ring:","marks":[{"type":"bold"}]},{"type":"text","text":" hash servers and keys onto the same circle (0…2³²−1, wraps around)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup:","marks":[{"type":"bold"}]},{"type":"text","text":" first server clockwise; in code, a sorted array + binary search, O(log(N·V))."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changes:","marks":[{"type":"bold"}]},{"type":"text","text":" add/remove moves only ~K/N keys, from/to the neighbours."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual nodes:","marks":[{"type":"bold"}]},{"type":"text","text":" 100–256 positions per server for even load, smooth scaling and weights."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replication:","marks":[{"type":"bold"}]},{"type":"text","text":" next R−1 distinct physical servers (rack/zone aware); R + W > N for consistency."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hot keys:","marks":[{"type":"bold"}]},{"type":"text","text":" balanced keys ≠ balanced traffic → bounded loads, key splitting, local caches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alternatives:","marks":[{"type":"bold"}]},{"type":"text","text":" rendezvous, jump hash, Maglev, range sharding (and Redis Cluster''s slots)."}]}]}]},{"type":"details","attrs":{"tone":"mint"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"The 60-second answer"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Plain modulo hashing reshuffles almost every key when a server is added or removed. Consistent hashing puts servers and keys on the same hash ring and gives each key to the next server clockwise, so a change only moves the keys in one arc, about K/N of them. Real systems give each server many virtual nodes to even out load and spread the impact of failures, replicate each key to the next few distinct servers, and handle hot keys separately because the ring balances keys, not traffic. Dynamo, Cassandra and memcached clients all work this way.\""}]}]}]},{"type":"table","attrs":{"visibility":"detail"},"content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Question you may get"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Short answer"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How many keys move when a node joins?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~K/N (its fair share), taken from its ring neighbours (from all nodes with vnodes)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Why virtual nodes?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Even load, smooth scaling, failure spread, weights"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the owner fast?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorted token array + binary search; rebuild on membership change"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How do replicas work?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Next distinct physical nodes clockwise; quorum R + W > N"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One key is extremely hot. Now what?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Bounded loads, split the key, cache it near clients"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Does Redis Cluster use this?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No: 16,384 hash slots"}]}]}]}]},{"type":"bulletList","attrs":{"visibility":"brief"},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Modulo → ring → clockwise owner → K/N moves → vnodes → replicas → hot keys → alternatives"}]}]}]}]}'::jsonb, canvas = '{"layout":"40-60","files":{},"elements":[{"id":"consistent-hashing-frame-1","type":"frame","x":0,"y":0,"width":1600,"height":1200,"name":"Why naive hashing breaks","seed":1,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"consistent-hashing-el-3","frameId":"consistent-hashing-fr